FILES={'gen3.py': b'"""P1-APP-01 \xeb\xb6\x80\xed\x95\x98 \xec\x83\x9d\xec\x84\xb1\xea\xb8\xb0 v3 \xe2\x80\x94 \xea\xb2\xb0\xec\xa0\x95\xec\x95\x88 v2 \xed\x94\x84\xeb\xa1\x9c\xed\x8c\x8c\xec\x9d\xbc(B 20 rps 600\xec\xb4\x88 -> P 50 rps 180\xec\xb4\x88 -> \xeb\xac\xb4\xeb\xb6\x80\xed\x95\x98 120\xec\xb4\x88).\n\n\xec\x8b\xa4\xed\x96\x89: python3 gen3.py <RUN> <OUT_DIR> > <OUT_DIR>/stages.log 2>&1\n\n\xec\x8b\xa4\xed\x8c\xa8\xed\x95\x98\xeb\xa9\xb4 \xeb\xa9\x88\xec\xb6\x98\xeb\x8b\xa4(fail-close):\n- \xeb\x8f\x99\xec\x8b\x9c \xec\x9a\x94\xec\xb2\xad\xec\x9d\x80 MAX_INFLIGHT\xea\xb0\x9c\xea\xb9\x8c\xec\xa7\x80\xeb\xa7\x8c \xeb\x91\x94\xeb\x8b\xa4. \xeb\xb3\xb4\xeb\x82\xbc \xec\x8b\x9c\xea\xb0\x81\xec\x97\x90 \xeb\xb9\x88\xec\x9e\x90\xeb\xa6\xac\xea\xb0\x80 \xec\x97\x86\xec\x9c\xbc\xeb\xa9\xb4 LOAD_GENERATOR_SATURATED\xeb\xa1\x9c\n  \xec\x83\x88 \xec\x9a\x94\xec\xb2\xad\xec\x9d\x84 \xeb\xa9\x88\xec\xb6\x98\xeb\x8b\xa4. \xec\x9a\x94\xec\xb2\xad\xec\x9d\xb4 \xeb\x8c\x80\xea\xb8\xb0\xec\x97\xb4\xec\x97\x90 \xec\x8c\x93\xec\x9d\xb4\xec\xa7\x80 \xec\x95\x8a\xec\x9c\xbc\xeb\xaf\x80\xeb\xa1\x9c \xeb\x8b\xa4\xec\x9d\x8c \xeb\x8b\xa8\xea\xb3\x84\xeb\x82\x98 \xea\xb4\x80\xec\xb0\xb0 \xea\xb5\xac\xea\xb0\x84\xec\x9c\xbc\xeb\xa1\x9c \xeb\x84\x98\xec\x96\xb4\xea\xb0\x80 \xec\x8b\x9c\xec\x9e\x91\xeb\x90\x98\xec\xa7\x80 \xec\x95\x8a\xeb\x8a\x94\xeb\x8b\xa4.\n- \xeb\x8b\xa8\xea\xb3\x84\xea\xb0\x80 \xeb\x81\x9d\xeb\x82\x98\xeb\xa9\xb4 \xea\xb7\xb8 \xeb\x8b\xa8\xea\xb3\x84 \xec\x9a\x94\xec\xb2\xad\xec\x9d\xb4 DRAIN\xec\xb4\x88 \xec\x95\x88\xec\x97\x90 \xeb\xaa\xa8\xeb\x91\x90 \xeb\x81\x9d\xeb\x82\x98\xec\x95\xbc \xeb\x8b\xa4\xec\x9d\x8c \xeb\x8b\xa8\xea\xb3\x84(\xeb\x98\x90\xeb\x8a\x94 \xea\xb4\x80\xec\xb0\xb0)\xeb\xa1\x9c \xea\xb0\x84\xeb\x8b\xa4.\n  \xec\x95\x84\xeb\x8b\x88\xeb\xa9\xb4 STAGE_NOT_DRAINED\xeb\xa1\x9c \xeb\xa9\x88\xec\xb6\x98\xeb\x8b\xa4.\n- PROGRESS\xec\xb4\x88 \xec\x82\xac\xec\x9d\xb4 201 \xec\x99\xb8 \xec\x9d\x91\xeb\x8b\xb5\xec\x9d\xb4 ERROR_STOP\xea\xb1\xb4 \xec\x9d\xb4\xec\x83\x81 \xeb\x8a\x98\xeb\xa9\xb4 ERROR_THRESHOLD\xeb\xa1\x9c \xeb\xa9\x88\xec\xb6\x98\xeb\x8b\xa4. \xeb\x8b\xa8\xea\xb3\x84\xea\xb0\x80 \xeb\x81\x9d\xeb\x82\x98 \xea\xb7\xb8 \xeb\x8b\xa8\xea\xb3\x84\n  \xec\x9a\x94\xec\xb2\xad\xec\x9d\xb4 \xeb\xaa\xa8\xeb\x91\x90 \xeb\x81\x9d\xeb\x82\x9c \xeb\x92\xa4\xec\x97\x90\xeb\x8f\x84 \xeb\xa7\x88\xec\xa7\x80\xeb\xa7\x89 \xec\xa7\x84\xed\x96\x89 \xea\xb8\xb0\xeb\xa1\x9d \xec\x9d\xb4\xed\x9b\x84 \xeb\x8a\x98\xec\x96\xb4\xeb\x82\x9c \xec\x88\x98\xeb\xa5\xbc \xea\xb0\x99\xec\x9d\x80 \xea\xb8\xb0\xec\xa4\x80\xec\x9c\xbc\xeb\xa1\x9c \xed\x95\x9c \xeb\xb2\x88 \xeb\x8d\x94 \xeb\xb3\xb8\xeb\x8b\xa4.\n\xeb\xa9\x88\xec\xb6\x94\xeb\xa9\xb4 \xec\x9d\xb4\xeb\xaf\xb8 \xeb\xb3\xb4\xeb\x82\xb8 \xec\x9a\x94\xec\xb2\xad\xec\x9d\xb4 \xeb\x81\x9d\xeb\x82\xa0 \xeb\x95\x8c\xea\xb9\x8c\xec\xa7\x80(\xec\x9a\x94\xec\xb2\xad\xeb\xa7\x88\xeb\x8b\xa4 TIMEOUT\xec\xb4\x88 \xec\x9d\xb4\xeb\x82\xb4) \xea\xb8\xb0\xeb\x8b\xa4\xeb\xa6\xb0 \xeb\x92\xa4 \xec\xa2\x85\xeb\xa3\x8c \xec\xbd\x94\xeb\x93\x9c 2\xeb\xa1\x9c \xeb\x81\x9d\xeb\x82\xb8\xeb\x8b\xa4.\n\xec\xa0\x95\xec\x83\x81 \xec\xa2\x85\xeb\xa3\x8c\xeb\x8a\x94 \xeb\x82\xa8\xec\x9d\x80 \xec\x9a\x94\xec\xb2\xad 0\xea\xb1\xb4\xec\x9d\x84 \xea\xb8\xb0\xeb\xa1\x9d\xed\x95\x98\xea\xb3\xa0 \xec\xa2\x85\xeb\xa3\x8c \xec\xbd\x94\xeb\x93\x9c 0\xec\x9d\xb4\xeb\x8b\xa4.\n"""\nimport argparse\nimport http.client\nimport json\nimport random\nimport sys\nimport threading\nimport time\nfrom concurrent.futures import ThreadPoolExecutor, wait\nfrom pathlib import Path\n\nTARGETS = (\'10.1.93.105\', \'10.1.93.107\', \'10.1.93.108\')\nPORT = 30080\nSTAGES = ((\'B\', 20, 600), (\'P\', 50, 180))\nREGRESSION_STAGES = ((\'B\', 20, 120), (\'P\', 50, 120))\nIDLE = 120\nMAX_INFLIGHT = 64\nTIMEOUT = 10\nDRAIN = 2\nPROGRESS = 30\nERROR_STOP = 10\n\n\ndef run(run_id, out_dir, targets=TARGETS, port=PORT, stages=STAGES, idle=IDLE, max_inflight=MAX_INFLIGHT,\n        timeout=TIMEOUT, drain=DRAIN, progress=PROGRESS, error_stop=ERROR_STOP, emit=None):\n    emit = emit or (lambda line: print(line, flush=True))\n\n    def log(*parts):\n        emit(\' \'.join([time.strftime(\'%H:%M:%S\')] + [str(p) for p in parts]))\n\n    rnd = random.Random(run_id)\n    lock = threading.Lock()\n    codes = {}\n    out = open(f\'{out_dir}/requests.log\', \'a\', encoding=\'utf-8\')\n\n    def send(i, stage, kind):\n        target = targets[i % len(targets)]\n        body = json.dumps({"account_id": f"SIM_load_{run_id}_{i}", "amount": 10000, "currency": "KRW",\n                           "transaction_type": kind, "source_ip": "198.51.100.10"})\n        t0 = time.time()\n        try:\n            conn = http.client.HTTPConnection(target, port, timeout=timeout)\n            conn.request(\'POST\', \'/api/v1/transactions\', body, {\'Content-Type\': \'application/json\'})\n            resp = conn.getresponse()\n            resp.read()\n            code = resp.status\n            conn.close()\n        except Exception:\n            code = -1\n        with lock:\n            out.write(f"{t0:.3f} {stage} {target} {kind} {code} {(time.time() - t0) * 1000:.1f}\\n")\n            codes[code] = codes.get(code, 0) + 1\n\n    def snapshot():\n        with lock:\n            out.flush()\n            return dict(codes)\n\n    def errors(counts):\n        return sum(n for code, n in counts.items() if code != 201)\n\n    stop = None\n    pending = set()\n    i = 0\n    with ThreadPoolExecutor(max_workers=max_inflight) as ex:\n        for stage, rps, duration in stages:\n            start = time.time()\n            log(\'START\', stage, rps, \'rps\', duration, \'s\', f\'{start:.3f}\')\n            sent = 0\n            stage_futures = []\n            next_progress = start + progress\n            last_errors = errors(snapshot())\n            while time.time() - start < duration:\n                if time.time() >= next_progress:\n                    counts = snapshot()\n                    log(\'..\', stage, \'sent\', sent, \'inflight\', sum(1 for f in pending if not f.done()), \'codes\', counts)\n                    if errors(counts) - last_errors >= error_stop:\n                        stop = \'ERROR_THRESHOLD\'\n                        break\n                    last_errors = errors(counts)\n                    next_progress += progress\n                delay = start + sent / rps - time.time()\n                if delay > 0:\n                    time.sleep(min(delay, 0.05))\n                    continue\n                pending = {f for f in pending if not f.done()}\n                if len(pending) >= max_inflight:\n                    stop = \'LOAD_GENERATOR_SATURATED\'\n                    break\n                x = rnd.random()\n                future = ex.submit(send, i, stage, \'deposit\' if x < 0.6 else (\'withdrawal\' if x < 0.8 else \'transfer\'))\n                pending.add(future)\n                stage_futures.append(future)\n                i += 1\n                sent += 1\n            if stop:\n                log(\'STOP\', stop, stage, \'sent\', sent, \'inflight\', sum(1 for f in pending if not f.done()), f\'{time.time():.3f}\')\n                break\n            log(\'END\', stage, \'sent\', sent, f\'{time.time():.3f}\')\n            _, not_done = wait([f for f in stage_futures if not f.done()], timeout=drain)\n            if not_done:\n                stop = \'STAGE_NOT_DRAINED\'\n                log(\'STOP\', stop, stage, \'outstanding\', len(not_done), f\'{time.time():.3f}\')\n                break\n            # \xeb\xa7\x88\xec\xa7\x80\xeb\xa7\x89 \xec\xa7\x84\xed\x96\x89 \xea\xb8\xb0\xeb\xa1\x9d \xeb\x92\xa4(\xeb\x8b\xa8\xea\xb3\x84 \xeb\x81\x9d\xea\xb9\x8c\xec\xa7\x80\xec\x99\x80 drain \xec\xa4\x91) \xeb\x8a\x98\xec\x96\xb4\xeb\x82\x9c 201 \xec\x99\xb8 \xec\x9d\x91\xeb\x8b\xb5\xeb\x8f\x84 \xea\xb0\x99\xec\x9d\x80 \xea\xb8\xb0\xec\xa4\x80\xec\x9c\xbc\xeb\xa1\x9c \xeb\xb3\xb8\xeb\x8b\xa4.\n            tail_errors = errors(snapshot()) - last_errors\n            if tail_errors >= error_stop:\n                stop = \'ERROR_THRESHOLD\'\n                log(\'STOP\', stop, stage, \'tail_errors\', tail_errors, f\'{time.time():.3f}\')\n                break\n            log(\'DRAINED\', stage, f\'{time.time():.3f}\')\n        if not stop:\n            log(\'IDLE START\', f\'{time.time():.3f}\')\n            time.sleep(idle)\n            log(\'IDLE END\', f\'{time.time():.3f}\', \'codes\', snapshot())\n    # with \xeb\xb8\x94\xeb\xa1\x9d\xec\x9d\x84 \xeb\x82\x98\xec\x98\xa4\xeb\xa9\xb4 \xec\x9d\xb4\xeb\xaf\xb8 \xeb\xb3\xb4\xeb\x82\xb8 \xec\x9a\x94\xec\xb2\xad\xec\x9d\x80 \xeb\xaa\xa8\xeb\x91\x90 \xeb\x81\x9d\xeb\x82\x9c \xec\x83\x81\xed\x83\x9c\xeb\x8b\xa4(\xec\x9a\x94\xec\xb2\xad\xeb\xa7\x88\xeb\x8b\xa4 timeout \xec\x9d\xb4\xeb\x82\xb4).\n    outstanding = sum(1 for f in pending if not f.done())\n    counts = snapshot()\n    out.close()\n    if stop or outstanding:\n        log(\'FAIL\', stop or \'OUTSTANDING\', \'outstanding\', outstanding, \'codes\', counts)\n        return 2\n    log(\'DONE\', \'outstanding\', outstanding, \'codes\', counts)\n    return 0\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'run_id\')\n    parser.add_argument(\'out_dir\')\n    parser.add_argument(\'--profile\', choices=(\'full\', \'regression\'), default=\'full\',\n                        help=\'full: existing 21000-request sizing; regression: approved 8400-request gate\')\n    args = parser.parse_args(argv)\n    if args.profile == \'full\':\n        return run(args.run_id, args.out_dir)\n\n    # The new profile cannot silently append another attempt to existing evidence.\n    # A fresh DB prefix check is still required: different directories do not imply a new RUN.\n    if len(args.run_id) != 12 or any(c not in \'0123456789\' for c in args.run_id):\n        parser.error(\'regression RUN must be a 12-digit identifier, fixed before execution\')\n    out = Path(args.out_dir)\n    if not out.is_dir():\n        parser.error(\'create a new output directory before execution\')\n    if (out / \'requests.log\').exists():\n        parser.error(\'requests.log already exists; preserve the previous attempt\')\n    record = {\'profile\': \'regression\', \'run_id\': args.run_id,\n              \'stages\': REGRESSION_STAGES, \'planned_requests\': 8400, \'idle_seconds\': IDLE,\n              \'max_inflight\': MAX_INFLIGHT, \'timeout_seconds\': TIMEOUT,\n              \'targets\': TARGETS, \'port\': PORT, \'purpose\': \'regression-only; no resource resizing\'}\n    try:\n        with (out / \'regression-attempt.json\').open(\'x\', encoding=\'utf-8\') as handle:\n            json.dump(record, handle, ensure_ascii=False, indent=2)\n            handle.write(\'\\n\')\n    except FileExistsError:\n        parser.error(\'regression attempt already claimed; no automatic rerun\')\n    print(\'PROFILE regression PLANNED_REQUESTS 8400 IDLE_SECONDS 120\', flush=True)\n    return run(args.run_id, args.out_dir, stages=REGRESSION_STAGES)\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n'}
HASHES={'gen3.py': 'e5942646ba2544275b7664bbbc296d841920a0d1dac23421f96f1cc20e766b29'}
